User save(User user) {
  try (PreparedStatement stmt = conn.prepareStatement("INSERT INTO users (email, first_name) VALUES (?,?)", Statement.RETURN_GENERATED_KEYS)) {
    stmt.setString(1, user.email()); stmt.setString(2, user.firstName());
    stmt.executeUpdate();
    try (ResultSet keys = stmt.getGeneratedKeys()) { keys.next(); return new User(keys.getLong(1), user.email(), user.firstName()); }
  } catch (SQLException e) { throw new RuntimeException(e); }
}

Optional<User> findById(long id) {
  try (PreparedStatement stmt = conn.prepareStatement("SELECT * FROM users WHERE id=?")) {
    stmt.setLong(1, id);
    try (ResultSet rs = stmt.executeQuery()) { return rs.next() ? Optional.of(mapRow(rs)) : Optional.empty(); }
  } catch (SQLException e) { throw new RuntimeException(e); }
}

List<User> findAll() {
  List<User> result = new ArrayList<>();
  try (Statement stmt = conn.createStatement(); ResultSet rs = stmt.executeQuery("SELECT * FROM users ORDER BY id")) {
    while (rs.next()) result.add(mapRow(rs));
    return result;
  } catch (SQLException e) { throw new RuntimeException(e); }
}

