    stmt.setInt(1, n);
    try (ResultSet rs = stmt.executeQuery()) {
      List<Product> result = new ArrayList<>();
      while (rs.next()) result.add(mapRow(rs));
      return result;
    }
  } catch (SQLException e) { throw new RuntimeException(e); }
}

